/* Featured Tamil artists mini-columns on landing */
.lingua-tamil-featured {
  display: flex;
  gap: 19px;
  align-items: stretch;
  padding: 8px 8px 8px 8px;
  overflow-x: auto;
  min-height: 320px;
  max-width: 610px;
  position: relative;
}
.tamil-mini-col {
  min-width: 130px;
  max-width: 145px;
  background: linear-gradient(145deg, #fff9fe 94%, #fde5ee 100%);
  border-radius: 12px;
  padding: 13px 8px 12px 8px;
  box-shadow: 0 2px 8px #fae4f1;
  border: 2.2px solid #f8bddd;
  display: flex;
  flex-direction: column;
  align-items: center;
  transition: transform 0.13s;
  outline: none;
  cursor: pointer;
}
.tamil-mini-col img {
  width: 68px;
  height: 68px;
  border-radius: 50%;
  object-fit: cover;
  margin-bottom: 7px;
  border: 2px solid #d68ad6;
  background: #e6e3ef;
}
.tamil-mini-col ul {
  list-style: square;
  font-size: 13px;
  color: #444;
  margin-left: 7px;
  margin-right: 5px;
  margin-bottom: 1px;
  padding-left: 12px;
}

/* Responsive hack for mobile and narrow screens */
@media (max-width: 700px) {
  .lingua-landing > div {
    flex-direction: column !important;
    width: 99vw !important;
    gap: 16px !important;
  }
  .lingua-tamil-featured {
    max-width: 97vw;
    min-width: 97vw;
    flex-wrap: nowrap;
    overflow-x: auto;
    padding: 8px 2% 12px 2%;
  }
  .tamil-mini-col {
    min-width: 90vw;
    max-width: 95vw;
    margin-right: 12px;
  }
